package org.jfree.chart.block;

import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.block.Block.RectangleConstraint;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.Size2D;
import org.jfree.data.Range;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BorderArrangement.arrangeNN.
 * Since arrangeNN is protected, we use a Testable subclass to expose it.
 */
public class BorderArrangement_arrangeNN_TriageGen0Test {

    private TestableBorderArrangement arrangement;
    private BlockContainer mockContainer;
    private Graphics2D mockGraphics;

    // Subclass to access protected method
    private static class TestableBorderArrangement extends BorderArrangement {
        public Size2D callArrangeNN(BlockContainer container, Graphics2D g2) {
            return super.arrangeNN(container, g2);
        }

        // Helper to inject blocks since fields are likely private/protected
        public void setTop(Block b) { this.topBlock = b; }
        public void setBottom(Block b) { this.bottomBlock = b; }
        public void setLeft(Block b) { this.leftBlock = b; }
        public void setRight(Block b) { this.rightBlock = b; }
        public void setCenter(Block b) { this.centerBlock = b; }
    }

    @Before
    public void setUp() {
        arrangement = new TestableBorderArrangement();
        mockContainer = mock(BlockContainer.class);
        mockGraphics = mock(Graphics2D.class);
    }

    @Test
    public void testArrangeNN_AllNull() {
        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);
        assertEquals(0.0, result.width, 1e-9);
        assertEquals(0.0, result.height, 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyTop() {
        Block top = mock(Block.class);
        when(top.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 50));
        arrangement.setTop(top);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        assertEquals(100.0, result.width, 1e-9);
        assertEquals(50.0, result.height, 1e-9);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(top).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getX(), 1e-9);
        assertEquals(0.0, captor.getValue().getY(), 1e-9);
        assertEquals(100.0, captor.getValue().getWidth(), 1e-9);
        assertEquals(50.0, captor.getValue().getHeight(), 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyBottom() {
        Block bottom = mock(Block.class);
        when(bottom.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 40));
        arrangement.setBottom(bottom);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        assertEquals(100.0, result.width, 1e-9);
        assertEquals(40.0, result.height, 1e-9);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(bottom).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getY(), 1e-9);
        assertEquals(40.0, captor.getValue().getHeight(), 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyLeftAndRight() {
        Block left = mock(Block.class);
        Block right = mock(Block.class);
        // Left: w=20, h=30 | Right: w=30, h=50
        when(left.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(20, 30));
        when(right.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(30, 50));
        arrangement.setLeft(left);
        arrangement.setRight(right);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        // h[2] = max(30, 50) = 50. h[3] = 50.
        // centerHeight = max(30, 50, 0) = 50.
        // width = max(0, 0, 20 + 0 + 30) = 50.
        // height = 0 + 0 + 50 = 50.
        assertEquals(50.0, result.width, 1e-9);
        assertEquals(50.0, result.height, 1e-9);

        ArgumentCaptor<Rectangle2D.Double> leftCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(left).setBounds(leftCaptor.capture());
        assertEquals(50.0, leftCaptor.getValue().getHeight(), 1e-9);

        ArgumentCaptor<Rectangle2D.Double> rightCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(right).setBounds(rightCaptor.capture());
        assertEquals(50.0 - 30.0, rightCaptor.getValue().getX(), 1e-9);
    }

    @Test
    public void testArrangeNN_FullLayout() {
        Block top = mock(Block.class);
        Block bottom = mock(Block.class);
        Block left = mock(Block.class);
        Block right = mock(Block.class);
        Block center = mock(Block.class);

        when(top.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 20));
        when(bottom.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 20));
        when(left.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(10, 40));
        when(right.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(10, 40));
        when(center.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(50, 40));

        arrangement.setTop(top);
        arrangement.setBottom(bottom);
        arrangement.setLeft(left);
        arrangement.setRight(right);
        arrangement.setCenter(center);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        // Calculations:
        // w[0]=100, w[1]=100, w[2]=10, w[3]=10, w[4]=50
        // h[0]=20, h[1]=20, h[2]=40, h[3]=40 (max of h2,h3), h[4]=40
        // width = max(100, 100, 10 + 50 + 10) = 100
        // centerHeight = max(40, 40, 40) = 40
        // height = 20 + 20 + 40 = 80

        assertEquals(100.0, result.width, 1e-9);
        assertEquals(80.0, result.height, 1e-9);

        // Verify Center Bounds
        ArgumentCaptor<Rectangle2D.Double> centerCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(center).setBounds(centerCaptor.capture());
        // center x = w[2] = 10
        // center y = h[0] = 20
        // center width = 100 - 10 - 10 = 80
        // center height = 40
        assertEquals(10.0, centerCaptor.getValue().getX(), 1e-9);
        assertEquals(20.0, centerCaptor.getValue().getY(), 1e-9);
        assertEquals(80.0, centerCaptor.getValue().getWidth(), 1e-9);
        assertEquals(40.0, centerCaptor.getValue().getHeight(), 1e-9);
    }

    @Test
    public void testArrangeNN_ComplexWidth() {
        // Test case where center + sides are wider than top/bottom
        Block top = mock(Block.class);
        Block left = mock(Block.class);
        Block center = mock(Block.class);
        Block right = mock(Block.class);

        when(top.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(50, 10));
        when(left.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(20, 20));
        when(center.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(100, 20));
        when(right.arrange(any(), eq(RectangleConstraint.NONE))).thenReturn(new Size2D(20, 20));

        arrangement.setTop(top);
        arrangement.setLeft(left);
        arrangement.setCenter(center);
        arrangement.setRight(right);

        Size2D result = arrangement.callArrangeNN(mockContainer, mockGraphics);

        // width = max(50, 0, 20 + 100 + 20) = 140
        assertEquals(140.0, result.width, 1e-9);
    }
}
